// Convert key/value rows from Config tab into a single config object,
// then expand keywords into one item per keyword.
const cfg = {};
for (const item of $input.all()) {
  const k = (item.json.key || '').toString().trim();
  const v = (item.json.value || '').toString().trim();
  if (k) cfg[k] = v;
}

const keywords = (cfg.keywords || '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

if (keywords.length === 0) {
  throw new Error('No keywords found in Config tab. Add a row with key=keywords.');
}

const location = cfg.location || '';
const max = parseInt(cfg.max_results_per_keyword || '20', 10);
const posted = cfg.posted_within || 'past_week';

return keywords.map(kw => ({
  json: {
    keyword: kw,
    location,
    max_results: max,
    posted_within: posted,
  },
}));

// Flatten SerpAPI jobs_results into one item per job.
const out = [];
const now = new Date().toISOString().slice(0, 10);

for (const item of $input.all()) {
  const keyword = item.json.keyword || '';
  const results = item.json.jobs_results || [];
  const max = item.json.max_results || 20;
  for (const j of results.slice(0, max)) {
    const applyLink =
      (j.apply_options && j.apply_options[0] && j.apply_options[0].link) ||
      j.share_link ||
      j.related_links?.[0]?.link ||
      '';
    out.push({
      json: {
        title: j.title || '',
        company: j.company_name || '',
        location: j.location || '',
        description: j.description || '',
        apply_link: applyLink,
        source: (j.via || 'Google Jobs').replace(/^via\s+/i, ''),
        date_added: now,
        keyword,
        detected_extensions: j.detected_extensions || {},
      },
    });
  }
}

return out;

// Dedupe new jobs against existing apply links in the Jobs sheet.
const existing = new Set();
for (const row of $('Read Existing Jobs').all()) {
  const link = (row.json['Link to Apply'] || row.json.link_to_apply || '').toString().trim();
  if (link) existing.add(link);
}

const fresh = [];
for (const item of $('Flatten Jobs').all()) {
  const link = (item.json.apply_link || '').toString().trim();
  if (!link) continue;
  if (existing.has(link)) continue;
  existing.add(link); // also dedupe within this run
  fresh.push(item);
}

return fresh;

