// Merge Gemini output back with the original job item, then build the
// row payload that matches the Jobs sheet column order.
const jobs = $('Dedupe vs Sheet').all();
const gemResp = $input.all();

const rows = [];
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i].json;
  let summary = '', eligibility = 'Not specified', pay = 'Not specified';
  try {
    const text =
      gemResp[i].json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    const parsed = JSON.parse(text);
    summary = parsed.summary || '';
    eligibility = parsed.eligibility || 'Not specified';
    pay = parsed.pay_range || 'Not specified';
  } catch (e) {
    summary = (job.description || '').slice(0, 280);
  }

  rows.push({
    json: {
      'Title': job.title,
      'Company': job.company,
      'Job Description Summary': summary,
      'Link to Apply': job.apply_link,
      'Eligibility': eligibility,
      'Location': job.location,
      'Pay Range': pay,
      'Source': job.source,
      'Date Added': job.date_added,
      'Status': 'New',
    },
  });
}

return rows;
